//! Byte-oracle tests for the mcp slice: every expectation was captured by
//! EXECUTING the actual upstream TypeScript (2bbfcca43, v0.99.1) under Node
//! `--experimental-strip-types` — see
//! `tests/fixtures/mcp_oracle/capture_mcp_oracle.mjs` (the generator, kept
//! with the fixture) and `mcp_oracle.manifest.json` (the SHA-256 provenance
//! of every captured source; the manifest hashes are re-verified against the
//! upstream tree by `manifest_hashes_match_upstream` below).
//!
//! Comparisons over JSON objects are canonical (serde_json `Value` equality,
//! which compares maps order-insensitively); the pinned contract is the key
//! SET and every value, plus the exact pinned strings (`initializeSent`,
//! `clientToServerHex`, request bodies, URLs). Node-only message texts
//! (V8 `SyntaxError` strings) are classified by kind instead, as disclosed
//! in each test.
//!
//! Determinism contract (see the manifest): draws come from
//! [`crate::mcp::test_rng`] (byte[i] = (k*32 + i) & 0xFF, reset per
//! scenario), the provider clock is pinned to the capture's `FIXED_NOW`, and
//! every HTTP scenario uses an injected recorder fetch — no network. The one
//! real loopback listener (OAuth callback) is hit with raw sockets. Tests
//! that consume the RNG or the clock take [`scenario_lock`] so they pass both
//! single- and multi-threaded.

use std::sync::Arc;
use std::sync::Mutex;

use futures::future::BoxFuture;
use serde_json::{json, Value};

use crate::mcp::client::{ClientState, McpClient, McpClientOptions, McpRequestOptions};
use crate::mcp::protocol::content::{to_llm_content, CallToolResult};
use crate::mcp::protocol::jsonrpc::{
    parse_json_rpc_message, JsonRpcId, JsonRpcMessage, JsonRpcResponse, McpClientError, McpError,
    JSON_RPC_ERROR_CODES_INVALID_REQUEST, JSON_RPC_ERROR_CODES_METHOD_NOT_FOUND,
    JSON_RPC_ERROR_CODES_PARSE_ERROR,
};
use crate::mcp::transports::{
    create_in_memory_transport_pair, McpTransport, TransportMessageListener, Unsubscribe,
};
use sha2::Digest;

/// The captured fixture (generated by the committed capture script against
/// upstream 2bbfcca43).
pub(crate) fn oracle() -> Value {
    serde_json::from_str(include_str!(
        "../../tests/fixtures/mcp_oracle/mcp_oracle.json"
    ))
    .expect("oracle fixture must parse")
}

/// The capture's fixed `Date.now()`.
pub(crate) const FIXED_NOW: u64 = 1_758_240_000_000;

/// Serializes RNG/clock-consuming scenarios (see the module docs). Async,
/// so the guard can be held across the scenario's awaits.
pub(crate) async fn scenario_lock() -> tokio::sync::MutexGuard<'static, ()> {
    static LOCK: tokio::sync::Mutex<()> = tokio::sync::Mutex::const_new(());
    LOCK.lock().await
}

/// Canonical JSON equality assertion with a context label.
pub(crate) fn assert_canonical(label: &str, actual: Value, expected: &Value) {
    assert_eq!(
        &actual, expected,
        "{label}: canonical JSON mismatch\n  actual:   {actual}\n  expected: {expected}"
    );
}

/// `JSON.stringify` of a JSON value (the pinned-string form).
pub(crate) fn stringify(value: &Value) -> String {
    serde_json::to_string(value).expect("serialization cannot fail")
}

/// The capture aliases the parsed message object with the input object, so
/// the fixture's `ok` may carry keys outside the message's kind (a stray
/// `result` on a request, for example); the port models one key set per
/// kind, which is the pinned contract here.
fn modeled_keys(expected: &Value) -> Value {
    let keep: &[&str] = if expected.get("method").is_some() && expected.get("id").is_some() {
        &["jsonrpc", "id", "method", "params"]
    } else if expected.get("method").is_some() {
        &["jsonrpc", "method", "params"]
    } else {
        &["jsonrpc", "id", "result", "error"]
    };
    expected
        .as_object()
        .map(|object| {
            object
                .iter()
                .filter(|(key, _)| keep.contains(&key.as_str()))
                .map(|(key, value)| (key.clone(), value.clone()))
                .collect::<serde_json::Map<String, Value>>()
        })
        .map(Value::Object)
        .unwrap_or_else(|| expected.clone())
}

/// Lets the in-memory delivery tasks run (upstream delivers on the
/// microtask queue; the port delivers from spawned tokio tasks).
pub(crate) async fn flush() {
    for _ in 0..50 {
        tokio::task::yield_now().await;
    }
}

// ---------------------------------------------------------------------------
// Shared doubles
// ---------------------------------------------------------------------------

pub(crate) type ServerHandler =
    Arc<dyn Fn(Value) -> BoxFuture<'static, Result<Value, McpError>> + Send + Sync>;
pub(crate) type ServerHandlerFuture = BoxFuture<'static, Result<Value, McpError>>;
/// The client.rs request-handler future (McpClientError error channel).
pub(crate) type RequestHandlerFuture = BoxFuture<'static, Result<Value, McpClientError>>;

/// A fake in-memory MCP server (mirrors the capture's `memoryServer`):
/// records every received message, dispatches to per-method handlers on a
/// spawned task.
pub(crate) struct MemoryServer {
    pub client: Arc<dyn McpTransport>,
    pub server: Arc<dyn McpTransport>,
    pub messages: Arc<Mutex<Vec<Value>>>,
    pub handlers: Arc<Mutex<std::collections::HashMap<String, ServerHandler>>>,
}

impl MemoryServer {
    pub async fn new() -> Self {
        let (client, server) = create_in_memory_transport_pair();
        let messages = Arc::new(Mutex::new(Vec::new()));
        let handlers: Arc<Mutex<std::collections::HashMap<String, ServerHandler>>> =
            Arc::new(Mutex::new(std::collections::HashMap::new()));
        let message_log = Arc::clone(&messages);
        let handler_map = Arc::clone(&handlers);
        let server_transport = Arc::clone(&server);
        let listener: TransportMessageListener = Arc::new(move |message: &_| {
            let value = message.to_value();
            message_log.lock().expect("log").push(value.clone());
            // Only requests dispatch to handlers (upstream checks
            // `!("id" in message) || !("method" in message)`).
            let JsonRpcMessage::Request { id, method, .. } = message else {
                return;
            };
            let id = id.clone();
            let method = method.clone();
            let handler = handler_map.lock().expect("handlers").get(&method).cloned();
            let server_transport = Arc::clone(&server_transport);
            tokio::spawn(async move {
                let response = match handler {
                    None => JsonRpcMessage::Response(JsonRpcResponse::Error {
                        id: id.clone(),
                        error: crate::mcp::protocol::jsonrpc::JsonRpcErrorObject::new(
                            JSON_RPC_ERROR_CODES_METHOD_NOT_FOUND,
                            format!("Method not found: {method}"),
                        ),
                    }),
                    Some(handler) => match handler(value).await {
                        Ok(result) => {
                            let result = if result.is_null() { json!({}) } else { result };
                            JsonRpcMessage::Response(JsonRpcResponse::Success {
                                id: id.clone(),
                                result,
                            })
                        }
                        Err(error) => JsonRpcMessage::Response(JsonRpcResponse::Error {
                            id: id.clone(),
                            error: {
                                let mut error_object =
                                    crate::mcp::protocol::jsonrpc::JsonRpcErrorObject::new(
                                        error.code,
                                        error.message.clone(),
                                    );
                                if let Some(data) = &error.data {
                                    error_object = error_object.with_data(data.clone());
                                }
                                error_object
                            },
                        }),
                    },
                };
                let _ = server_transport.send(&response).await;
            });
        });
        server.on_message(listener);
        server.start().await.expect("server start");
        MemoryServer {
            client,
            server,
            messages,
            handlers,
        }
    }

    /// The initialize answer every scenario shares.
    pub async fn with_default_initialize() -> Self {
        let server = Self::new().await;
        server.set_handler(
            "initialize",
            value_handler(json!({
                "protocolVersion": "2025-06-18",
                "capabilities": { "tools": { "listChanged": true } },
                "serverInfo": { "name": "test-server", "version": "1.0.0" },
                "instructions": "Use test tools.",
            })),
        );
        server
    }

    /// The minimal initialize answer (`client_state_errors` et al.).
    pub async fn with_minimal_initialize() -> Self {
        let server = Self::new().await;
        server.set_handler(
            "initialize",
            value_handler(json!({
                "protocolVersion": "2025-06-18",
                "capabilities": {},
                "serverInfo": { "name": "s", "version": "1" },
            })),
        );
        server
    }

    pub fn set_handler(&self, method: &str, handler: ServerHandler) {
        self.handlers
            .lock()
            .expect("handlers")
            .insert(method.to_string(), handler);
    }

    pub fn sent(&self) -> Vec<Value> {
        self.messages.lock().expect("log").clone()
    }

    pub fn sent_strings(&self) -> Vec<String> {
        self.sent().iter().map(stringify).collect()
    }

    /// Requests with the given method, serialized (the capture's
    /// `messages.filter((m) => m.method === X).map(str)`).
    pub fn requests_for(&self, method: &str) -> Vec<String> {
        self.sent()
            .iter()
            .filter(|message| message.get("method").and_then(Value::as_str) == Some(method))
            .map(stringify)
            .collect()
    }
}

/// Result-shaped value handler.
pub(crate) fn value_handler(result: Value) -> ServerHandler {
    Arc::new(move |_request: Value| {
        let result = result.clone();
        Box::pin(async move { Ok(result) }) as ServerHandlerFuture
    })
}

/// The never-answering handler (upstream `() => new Promise(() => {})`): the
/// future never resolves, so the request can only end by timeout,
/// cancellation or connection loss.
pub(crate) fn never_handler() -> ServerHandler {
    Arc::new(|_request: Value| {
        Box::pin(async move {
            std::future::pending::<()>().await;
            Ok(Value::Null)
        }) as ServerHandlerFuture
    })
}

fn default_options() -> McpClientOptions {
    McpClientOptions::new("pi", "1")
}

/// The pinned roots list (`client_handshake` and `client_server_requests`).
fn roots(names: &[(&str, Option<&str>)]) -> crate::mcp::client::RootsProvider {
    crate::mcp::client::RootsProvider::List(Arc::new(
        names
            .iter()
            .map(|(uri, name)| crate::mcp::protocol::types::Root {
                uri: uri.to_string(),
                name: name.map(str::to_string),
                extra: Default::default(),
            })
            .collect(),
    ))
}

