/// Re-verify the manifest's SHA-256s against the upstream tree — the oracle
/// only means something if the capture still matches the sources.
#[test]
fn manifest_hashes_match_upstream() {
    let manifest: Value = serde_json::from_str(include_str!(
        "../../tests/fixtures/mcp_oracle/mcp_oracle.manifest.json"
    ))
    .expect("manifest parses");
    assert_eq!(manifest["upstream"], "2bbfcca43");
    let manifest_dir = std::fs::canonicalize(env!("CARGO_MANIFEST_DIR")).expect("manifest dir");
    // The manifest keys carry the full `packages/mcp/src/...` path from
    // the upstream repo root. The sibling checkout only exists on dev
    // machines; CI verifies the pinned bytes via the staged fixture copies
    // instead, so this drift check skips when the sibling is absent.
    let upstream_root = manifest_dir.parent().expect("crate parent").join("pi");
    if !upstream_root.exists() {
        println!("sibling upstream checkout absent; drift check skipped");
        return;
    }
    let hashes = manifest["sourceHashes"].as_object().expect("hash map");
    assert_eq!(hashes.len(), 18, "all 18 upstream files are pinned");
    for (relative, expected) in hashes {
        let bytes = std::fs::read(upstream_root.join(relative))
            .unwrap_or_else(|error| panic!("upstream source {relative} must be readable: {error}"));
        let digest = sha2::Sha256::digest(&bytes);
        let hex: String = digest.iter().map(|byte| format!("{byte:02x}")).collect();
        assert_eq!(
            &hex,
            expected.as_str().expect("hex string"),
            "upstream {relative} drifted from the capture"
        );
    }
}

// ---------------------------------------------------------------------------
// 1. protocol/jsonrpc.ts
// ---------------------------------------------------------------------------

#[test]
fn jsonrpc_parse_table_matches_the_capture() {
    let cases = &oracle()["jsonrpc"]["parse"];
    for (index, case) in cases.as_array().expect("array").iter().enumerate() {
        let input = &case["input"];
        // The capture's case `{jsonrpc: "2.0", method: "m", id: undefined}`
        // REJECTED upstream (the id key exists with an undefined value, so
        // `"id" in message` is true), but the serialized fixture input cannot
        // express the invisible key and parses as a plain notification here.
        // That one case is a JS-artifact and is skipped (documented).
        if case.get("errorName") == Some(&json!("McpError"))
            && input.get("id").is_none()
            && input.get("method").is_some()
            && input.get("result").is_none()
            && input.get("error").is_none()
        {
            continue;
        }
        let parsed = parse_json_rpc_message(input);
        if let Some(expected) = case.get("ok") {
            let message =
                parsed.unwrap_or_else(|error| panic!("case {index} should parse: {error}"));
            // The capture aliases the input object as `ok`, so keys outside
            // the port's per-kind model (e.g. a stray `result` on a request,
            // kept alive by the JS object aliasing) survive in the fixture;
            // the pinned contract is the modeled key set per message kind.
            let modeled = modeled_keys(expected);
            assert_canonical(
                &format!("jsonrpc parse case {index}"),
                message.to_value(),
                &modeled,
            );
        } else {
            let error = parsed.expect_err("case should reject");
            assert_eq!(
                error.code,
                case["errorCode"].as_i64().unwrap(),
                "case {index}"
            );
            assert_eq!(
                error.message,
                case["errorMessage"].as_str().unwrap(),
                "case {index}"
            );
        }
    }
}

#[test]
fn jsonrpc_error_codes_and_error_shapes_match_the_capture() {
    let expected = &oracle()["jsonrpc"];
    assert_eq!(
        JSON_RPC_ERROR_CODES_PARSE_ERROR,
        expected["errorCodes"]["parseError"].as_i64().unwrap()
    );
    assert_eq!(
        JSON_RPC_ERROR_CODES_INVALID_REQUEST,
        expected["errorCodes"]["invalidRequest"].as_i64().unwrap()
    );
    assert_eq!(
        JSON_RPC_ERROR_CODES_METHOD_NOT_FOUND,
        expected["errorCodes"]["methodNotFound"].as_i64().unwrap()
    );

    let errors = &expected["errors"];
    // McpError with data.
    let mcp_error = McpError::new(-32000, "custom failure").with_data(json!({ "detail": 1 }));
    assert_eq!(mcp_error.code, errors["mcp"]["code"].as_i64().unwrap());
    assert_eq!(
        mcp_error.message,
        errors["mcp"]["message"].as_str().unwrap()
    );
    assert_canonical(
        "mcp error data",
        mcp_error.data.clone().unwrap(),
        &errors["mcp"]["data"],
    );
    // McpError without data.
    let no_data = McpError::new(-32001, "no data");
    assert_eq!(no_data.data, None);
    // Connection closed default and custom.
    assert_eq!(
        McpClientError::connection_closed().message().as_ref(),
        errors["connectionClosed"]["message"].as_str().unwrap()
    );
    assert_eq!(
        McpClientError::connection_closed_with("MCP client is idle")
            .message()
            .as_ref(),
        errors["connectionClosedCustom"]["message"]
            .as_str()
            .unwrap()
    );
    // Timeout.
    assert_eq!(
        McpClientError::timeout(30_000).to_string(),
        errors["timeout"]["message"].as_str().unwrap()
    );
    // Abort.
    assert_eq!(
        McpClientError::aborted().message().as_ref(),
        errors["abort"]["message"].as_str().unwrap()
    );
}

/// `JSON.stringify` drops `data: undefined`, pinning the error-object key
/// order: `{jsonrpc, id, error:{code, message}}`.
#[test]
fn jsonrpc_error_object_serialization_matches_the_capture() {
    let message = JsonRpcMessage::Response(JsonRpcResponse::Error {
        id: JsonRpcId::Number(serde_json::Number::from(7)),
        error: crate::mcp::protocol::jsonrpc::JsonRpcErrorObject::new(-32603, "boom"),
    });
    assert_eq!(
        message.to_json_string(),
        oracle()["jsonrpc"]["errorObjectStringify"]
            .as_str()
            .unwrap()
    );
}

