#[test]
fn content_to_llm_content_matches_the_capture() {
    let results = vec![
        json!({ "content": [{ "type": "text", "text": "plain" }] }),
        json!({ "content": [{ "type": "image", "data": "AAAA", "mimeType": "image/png" }] }),
        json!({ "content": [{ "type": "audio", "data": "AAAA", "mimeType": "audio/wav" }] }),
        json!({ "content": [{ "type": "resource_link", "uri": "file:///x", "name": "x" }] }),
        json!({ "content": [{ "type": "resource", "resource": { "uri": "file:///t", "text": "inner" } }] }),
        json!({ "content": [{ "type": "resource", "resource": { "uri": "file:///i", "blob": "AAAA", "mimeType": "image/jpeg" } }] }),
        json!({ "content": [{ "type": "resource", "resource": { "uri": "file:///b", "blob": "AAAA" } }] }),
        json!({ "content": [{ "type": "resource", "resource": { "uri": "file:///b", "blob": "AAAA", "mimeType": "application/pdf" } }] }),
        json!({ "content": [{ "type": "weird", "extra": true }] }),
        json!({ "content": [], "structuredContent": { "answer": 42, "nested": { "a": [1, 2] } } }),
        json!({ "content": [{ "type": "text", "text": "keep" }], "structuredContent": { "ignored": true } }),
        json!({ "structuredContent": { "only": true } }),
    ];
    let oracle = oracle();
    let blocks = oracle["content"]["blocks"].as_array().expect("blocks");
    assert_eq!(results.len(), blocks.len());
    for (index, result) in results.iter().enumerate() {
        let call_result: CallToolResult =
            serde_json::from_value(result.clone()).expect("call tool result parses");
        let converted: Vec<Value> = to_llm_content(&call_result)
            .iter()
            .map(|item| serde_json::to_value(item).expect("serialize"))
            .collect();
        assert_canonical(
            &format!("content block {index}"),
            Value::Array(converted),
            &blocks[index],
        );
    }
}

