#[tokio::test(start_paused = true)]
async fn client_handshake_matches_the_capture() {
    let _guard = scenario_lock().await;
    let server = MemoryServer::with_default_initialize().await;
    server.set_handler("ping", value_handler(json!({})));
    let mut options = McpClientOptions::new("pi", "1.2.3");
    options.title = Some("Pi".to_string());
    options.capabilities = Some(serde_json::from_value(json!({ "sampling": {} })).unwrap());
    options.roots = Some(roots(&[("file:///work", Some("work"))]));
    let client = McpClient::new(options);
    let result = client
        .connect(Arc::clone(&server.client))
        .await
        .expect("connect");
    flush().await;
    let sent = server.sent_strings();
    let expected = &oracle()["client_handshake"];
    assert_eq!(sent[0], expected["initializeSent"].as_str().unwrap());
    assert_eq!(sent[1], expected["initializedSent"].as_str().unwrap());
    assert_eq!(
        client.protocol_version().unwrap(),
        expected["protocolVersion"].as_str().unwrap()
    );
    assert_canonical(
        "serverInfo",
        client.server_info().unwrap(),
        &expected["serverInfo"],
    );
    assert_canonical(
        "serverCapabilities",
        Value::Object(client.server_capabilities().unwrap()),
        &expected["serverCapabilities"],
    );
    assert_eq!(
        client.instructions().unwrap(),
        expected["instructions"].as_str().unwrap()
    );
    assert_eq!(client.connection_state(), ClientState::Connected);
    assert_canonical(
        "connect result",
        serde_json::to_value(&result).unwrap(),
        &expected["result"],
    );
    client
        .ping(McpRequestOptions::default())
        .await
        .expect("ping");
    flush().await;
    let expected_after: Vec<String> = expected["afterHandshake"]
        .as_array()
        .unwrap()
        .iter()
        .map(|value| value.as_str().unwrap().to_string())
        .collect();
    assert_eq!(&server.sent_strings()[2..], &expected_after[..]);
    client.close().await.expect("close");
    assert_eq!(client.connection_state(), ClientState::Closed);
    let error = client
        .connect(Arc::clone(&server.client))
        .await
        .expect_err("reconnect must fail");
    assert_eq!(
        error.to_string(),
        expected["reconnectError"].as_str().unwrap()
    );
}

#[tokio::test(start_paused = true)]
async fn client_state_errors_match_the_capture() {
    let expected = &oracle()["client_state_errors"];
    let idle = McpClient::new(default_options());
    let error = idle
        .request("ping", None, McpRequestOptions::default())
        .await
        .expect_err("request in idle state");
    assert_eq!(
        error.to_string(),
        expected["requestIdle"]["message"].as_str().unwrap()
    );
    let error = idle
        .notify("x", None)
        .await
        .expect_err("notify in idle state");
    assert_eq!(
        error.to_string(),
        expected["notifyIdle"]["message"].as_str().unwrap()
    );

    let server = MemoryServer::with_minimal_initialize().await;
    let connected = McpClient::new(default_options());
    connected
        .connect(Arc::clone(&server.client))
        .await
        .expect("connect");
    let error = connected
        .connect(Arc::clone(&server.client))
        .await
        .expect_err("second connect");
    assert_eq!(
        error.to_string(),
        expected["connectTwice"].as_str().unwrap()
    );

    // Unsupported protocol version.
    let bad_server = MemoryServer::new().await;
    bad_server.set_handler(
        "initialize",
        value_handler(json!({
            "protocolVersion": "1999-01-01",
            "capabilities": {},
            "serverInfo": { "name": "s", "version": "0" },
        })),
    );
    let bad_version = McpClient::new(default_options());
    let error = bad_version
        .connect(Arc::clone(&bad_server.client))
        .await
        .expect_err("unsupported version");
    assert_eq!(
        error.to_string(),
        expected["unsupportedVersion"].as_str().unwrap()
    );

    // Invalid initialize result.
    let invalid_server = MemoryServer::new().await;
    invalid_server.set_handler(
        "initialize",
        value_handler(json!({
            "protocolVersion": "2025-06-18",
            "capabilities": {},
            "serverInfo": { "name": 4, "version": "0" },
        })),
    );
    let bad_init = McpClient::new(default_options());
    let error = bad_init
        .connect(Arc::clone(&invalid_server.client))
        .await
        .expect_err("invalid initialize");
    let McpClientError::Mcp(mcp_error) = error else {
        panic!("expected McpError, got {error:?}");
    };
    assert_eq!(
        mcp_error.code,
        expected["invalidInitialize"]["code"].as_i64().unwrap()
    );
    assert_eq!(
        mcp_error.message,
        expected["invalidInitialize"]["message"].as_str().unwrap()
    );
}

#[tokio::test(start_paused = true)]
async fn client_request_shapes_match_the_capture() {
    let expected = &oracle()["client_request_shapes"];
    let server = MemoryServer::with_default_initialize().await;
    server.set_handler("ping", value_handler(json!({})));
    server.set_handler(
        "tools/list",
        value_handler(json!({
            "tools": [{ "name": "a", "inputSchema": { "type": "object" } }],
            "_meta": { "total": 1 },
        })),
    );
    let tools_handler: ServerHandler = Arc::new(|request| {
        Box::pin(async move {
            if request["params"]["name"] == "echo" {
                Ok(
                    json!({ "content": [{ "type": "text", "text": "hi" }], "structuredContent": { "v": 1 } }),
                )
            } else {
                Ok(json!({ "structuredContent": { "only": "structured" } }))
            }
        })
    });
    server.set_handler("tools/call", tools_handler);
    server.set_handler(
        "resources/read",
        value_handler(json!({ "contents": [{ "uri": "file:///x", "text": "data" }] })),
    );
    let pages = Arc::new(std::sync::atomic::AtomicUsize::new(0));
    let resource_pages = Arc::clone(&pages);
    server.set_handler(
        "resources/list",
        Arc::new(move |_request: Value| {
            let page = resource_pages.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
            Box::pin(async move {
                if page == 0 {
                    Ok(json!({ "resources": [
                        { "uri": "file:///a", "name": "a" },
                        { "uri": "file:///b" },
                    ] }))
                } else {
                    Ok(json!({ "resources": [{ "uri": "file:///c" }], "nextCursor": "page2" }))
                }
            }) as ServerHandlerFuture
        }) as ServerHandler,
    );
    server.set_handler(
        "resources/templates/list",
        value_handler(json!({ "resourceTemplates": [{ "uriTemplate": "t://{x}" }] })),
    );

    let client = McpClient::new(default_options());
    client
        .connect(Arc::clone(&server.client))
        .await
        .expect("connect");
    flush().await;
    client
        .list_tools(McpRequestOptions::default())
        .await
        .expect("list tools");
    let echo = client
        .call_tool(
            "echo",
            Some(serde_json::from_value(json!({ "text": "hello" })).unwrap()),
            McpRequestOptions::default(),
        )
        .await
        .expect("echo");
    let bare = client
        .call_tool("noargs", None, McpRequestOptions::default())
        .await
        .expect("bare");
    let read = client
        .read_resource("file:///x", McpRequestOptions::default())
        .await
        .expect("read");
    let resources = client
        .list_resources(McpRequestOptions::default())
        .await
        .expect("resources");
    let templates = client
        .list_resource_templates(McpRequestOptions::default())
        .await
        .expect("templates");

    let find = |sent: &[Value], label: &str, predicate: &dyn Fn(&Value) -> bool| -> String {
        match sent.iter().find(|message| predicate(message)) {
            Some(message) => stringify(message),
            None => panic!("request recorded: {label}; log = {:?}", sent),
        }
    };
    let sent = server.sent();
    assert_eq!(
        find(&sent, "toolsList", &|message| message["method"]
            == "tools/list"),
        expected["requests"]["toolsList"].as_str().unwrap()
    );
    assert_eq!(
        find(&sent, "toolsCallWithArgs", &|message| message["method"]
            == "tools/call"
            && message["params"]["name"] == "echo"),
        expected["requests"]["toolsCallWithArgs"].as_str().unwrap()
    );
    assert_eq!(
        find(&sent, "toolsCallBare", &|message| message["method"]
            == "tools/call"
            && message["params"]["name"] == "noargs"),
        expected["requests"]["toolsCallBare"].as_str().unwrap()
    );
    assert_eq!(
        find(&sent, "resourcesRead", &|message| message["method"]
            == "resources/read"),
        expected["requests"]["resourcesRead"].as_str().unwrap()
    );
    assert_eq!(
        find(&sent, "resourcesListPage1", &|message| message["method"]
            == "resources/list"
            && message.get("params").is_none()),
        expected["requests"]["resourcesListPage1"].as_str().unwrap()
    );
    assert_eq!(
        find(&sent, "resourcesTemplates", &|message| message["method"]
            == "resources/templates/list"),
        expected["requests"]["resourcesTemplates"].as_str().unwrap()
    );

    assert_canonical(
        "echo",
        serde_json::to_value(&echo).unwrap(),
        &expected["callToolEcho"],
    );
    assert_canonical(
        "bare",
        serde_json::to_value(&bare).unwrap(),
        &expected["callToolBare"],
    );
    assert_canonical(
        "read",
        serde_json::to_value(&read).unwrap(),
        &expected["readResource"],
    );
    assert_canonical(
        "resources",
        Value::Array(
            resources
                .iter()
                .map(|resource| serde_json::to_value(resource).unwrap())
                .collect(),
        ),
        &expected["resources"],
    );
    assert_canonical(
        "templates",
        Value::Array(
            templates
                .iter()
                .map(|template| serde_json::to_value(template).unwrap())
                .collect(),
        ),
        &expected["templates"],
    );
    server.set_handler(
        "custom/method",
        Arc::new(|request: Value| {
            Box::pin(async move { Ok(json!({ "saw": request["params"] })) }) as ServerHandlerFuture
        }),
    );
    let mut custom_params = serde_json::Map::new();
    custom_params.insert("z".into(), json!(1));
    custom_params.insert("a".into(), json!(2));
    let custom = client
        .request(
            "custom/method",
            Some(custom_params),
            McpRequestOptions::default(),
        )
        .await
        .expect("custom");
    assert_canonical("custom", custom, &expected["custom"]);
    flush().await;
    let all_request_ids: Vec<Value> = server
        .sent()
        .iter()
        .filter(|message| message.get("id").is_some())
        .map(|message| message["id"].clone())
        .collect();
    assert_canonical(
        "ids",
        Value::Array(all_request_ids),
        &expected["allRequestIds"],
    );
    client.close().await.expect("close");
    let _ = pages.load(std::sync::atomic::Ordering::SeqCst);
}

#[tokio::test(start_paused = true)]
async fn client_pagination_matches_the_capture() {
    let expected = &oracle()["client_pagination"];
    let server = MemoryServer::with_default_initialize().await;
    server.set_handler("ping", value_handler(json!({})));
    let client = McpClient::new(default_options());
    client
        .connect(Arc::clone(&server.client))
        .await
        .expect("connect");

    // Duplicate cursor.
    let duplicate_pages = Arc::new(std::sync::atomic::AtomicUsize::new(0));
    let pages_for_duplicate = Arc::clone(&duplicate_pages);
    server.set_handler(
        "tools/list",
        Arc::new(move |_request: Value| {
            let page = pages_for_duplicate.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
            Box::pin(async move {
                if page == 0 {
                    Ok(json!({ "tools": [{ "name": "a", "inputSchema": {} }], "nextCursor": "c1" }))
                } else {
                    Ok(json!({ "tools": [{ "name": "b", "inputSchema": {} }], "nextCursor": "c1" }))
                }
            }) as ServerHandlerFuture
        }) as ServerHandler,
    );
    let error = client
        .list_tools(McpRequestOptions::default())
        .await
        .expect_err("duplicate cursor");
    assert_eq!(
        error.to_string(),
        expected["duplicateCursor"].as_str().unwrap()
    );

    // Multi-page list.
    let multi_pages = Arc::new(std::sync::atomic::AtomicUsize::new(0));
    let pages_for_multi = Arc::clone(&multi_pages);
    server.set_handler(
        "tools/list",
        Arc::new(move |request: Value| {
            let page = pages_for_multi.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
            let _ = page;
            Box::pin(async move {
                let cursor = request["params"]["cursor"].as_str().map(str::to_string);
                match cursor.as_deref() {
                    None => Ok(json!({ "tools": [{ "name": "0", "inputSchema": {} }], "nextCursor": "p1" })),
                    Some("p1") => Ok(json!({ "tools": [{ "name": "1", "inputSchema": {} }], "nextCursor": "p2" })),
                    _ => Ok(json!({ "tools": [{ "name": "2", "inputSchema": {} }] })),
                }
            }) as ServerHandlerFuture
        }) as ServerHandler,
    );
    let tools = client
        .list_tools(McpRequestOptions::default())
        .await
        .expect("multi page");
    assert_canonical(
        "multi page",
        Value::Array(
            tools
                .iter()
                .map(|tool| serde_json::to_value(tool).unwrap())
                .collect(),
        ),
        &expected["multiPage"],
    );

    // Single-page surfaces with cursors.
    let resource_pages = Arc::new(std::sync::atomic::AtomicUsize::new(0));
    let resource_page_count = Arc::clone(&resource_pages);
    server.set_handler(
        "resources/list",
        Arc::new(move |_request: Value| {
            let page = resource_page_count.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
            Box::pin(async move {
                if page == 0 {
                    Ok(json!({ "resources": [{ "uri": "file:///1", "name": "one" }], "nextCursor": "z" }))
                } else {
                    Ok(json!({ "resources": [{ "uri": "file:///2", "name": "two" }] }))
                }
            }) as ServerHandlerFuture
        }) as ServerHandler,
    );
    let first_page = client
        .list_resources_page(None, McpRequestOptions::default())
        .await
        .expect("first page");
    let second_page = client
        .list_resources_page(first_page.next_cursor.clone(), McpRequestOptions::default())
        .await
        .expect("second page");
    assert_canonical(
        "resource pages",
        json!([first_page, second_page]),
        &expected["resourcesPages"],
    );
    let expected_page_requests: Vec<String> = expected["pageRequests"]
        .as_array()
        .unwrap()
        .iter()
        .map(|value| value.as_str().unwrap().to_string())
        .collect();
    assert_eq!(
        &server.requests_for("resources/list")[..],
        &expected_page_requests[..]
    );

    // Validation failures.
    let failures: Vec<(&str, &str, ServerHandler)> = vec![
        (
            "invalidList",
            "tools/list",
            value_handler(json!({ "tools": "not an array" })),
        ),
        (
            "invalidEntry",
            "tools/list",
            value_handler(json!({ "tools": [{ "inputSchema": {} }] })),
        ),
        (
            "invalidCursor",
            "tools/list",
            value_handler(json!({ "tools": [], "nextCursor": 5 })),
        ),
        (
            "invalidContents",
            "resources/read",
            value_handler(json!({ "contents": [{ "uri": "file:///x" }] })),
        ),
        (
            "invalidCallResult",
            "tools/call",
            value_handler(json!({ "content": "nope" })),
        ),
        (
            "invalidStructured",
            "tools/call",
            value_handler(json!({ "content": [], "structuredContent": [1] })),
        ),
    ];
    for (label, method, handler) in failures {
        server.set_handler(method, handler);
        let error = match method {
            "tools/list" => client
                .list_tools(McpRequestOptions::default())
                .await
                .expect_err(label),
            "resources/read" => client
                .read_resource("file:///x", McpRequestOptions::default())
                .await
                .expect_err(label),
            _ => client
                .call_tool("x", None, McpRequestOptions::default())
                .await
                .expect_err(label),
        };
        let McpClientError::Mcp(mcp_error) = error else {
            panic!("{label}: expected McpError, got {error:?}");
        };
        assert_eq!(
            mcp_error.code,
            expected[label]["code"].as_i64().unwrap(),
            "{label}"
        );
        assert_eq!(
            mcp_error.message,
            expected[label]["message"].as_str().unwrap(),
            "{label}"
        );
    }
    client.close().await.expect("close");
    let _ = (
        duplicate_pages.load(std::sync::atomic::Ordering::SeqCst),
        multi_pages.load(std::sync::atomic::Ordering::SeqCst),
    );
}

#[tokio::test(start_paused = true)]
async fn client_progress_matches_the_capture() {
    let expected = &oracle()["client_progress"];
    let server = MemoryServer::with_default_initialize().await;
    server.set_handler("ping", value_handler(json!({})));
    let push_transport = Arc::clone(&server.server);
    server.set_handler(
        "long/op",
        Arc::new(move |request: Value| {
            let transport = Arc::clone(&push_transport);
            let token = request["params"]["_meta"]["progressToken"].clone();
            Box::pin(async move {
                let first = tokio::spawn({
                    let transport = Arc::clone(&transport);
                    let token = token.clone();
                    async move {
                        tokio::time::sleep(std::time::Duration::from_millis(10)).await;
                        let _ = transport
                            .send(&JsonRpcMessage::Notification {
                                method: "notifications/progress".to_string(),
                                params: Some(json!({
                                    "progressToken": token, "progress": 1,
                                    "total": 2, "message": "half",
                                })),
                            })
                            .await;
                    }
                });
                let second = tokio::spawn({
                    let transport = Arc::clone(&transport);
                    let token = token.clone();
                    async move {
                        tokio::time::sleep(std::time::Duration::from_millis(20)).await;
                        let _ = transport
                            .send(&JsonRpcMessage::Notification {
                                method: "notifications/progress".to_string(),
                                params: Some(json!({ "progressToken": token, "progress": 2 })),
                            })
                            .await;
                    }
                });
                let _ = (first.await, second.await);
                Ok(json!({ "done": true }))
            }) as ServerHandlerFuture
        }) as ServerHandler,
    );
    let client = McpClient::new(default_options());
    client
        .connect(Arc::clone(&server.client))
        .await
        .expect("connect");
    let progress_events = Arc::new(Mutex::new(Vec::new()));
    let listener = {
        let events = Arc::clone(&progress_events);
        Arc::new(move |progress: &Value| {
            events.lock().expect("events").push(progress.clone());
        })
    };
    let options = McpRequestOptions {
        on_progress: Some(listener),
        timeout_ms: Some(5_000),
        ..McpRequestOptions::default()
    };
    let mut params = serde_json::Map::new();
    params.insert("q".into(), json!(1));
    let result = client
        .request("long/op", Some(params), options)
        .await
        .expect("long op");
    assert_canonical("result", result, &expected["result"]);
    assert_eq!(
        server.requests_for("long/op")[0],
        expected["longOpRequest"].as_str().unwrap()
    );
    assert_canonical(
        "progress events",
        Value::Array(progress_events.lock().expect("events").clone()),
        &expected["progressEvents"],
    );
    // A progress notification for an unknown token is ignored.
    let _ = server
        .server
        .send(&JsonRpcMessage::Notification {
            method: "notifications/progress".to_string(),
            params: Some(json!({ "progressToken": 9999, "progress": 1 })),
        })
        .await;
    client.close().await.expect("close");
}

#[tokio::test(start_paused = true)]
async fn client_abort_and_timeout_match_the_capture() {
    let expected = &oracle()["client_abort_and_timeout"];
    let server = MemoryServer::with_default_initialize().await;
    server.set_handler("ping", value_handler(json!({})));
    server.set_handler("slow", never_handler());
    server.set_handler(
        "eventual",
        Arc::new(|_request: Value| {
            Box::pin(async move {
                tokio::time::sleep(std::time::Duration::from_millis(40)).await;
                Ok(json!({ "late": true }))
            }) as ServerHandlerFuture
        }) as ServerHandler,
    );
    let client = McpClient::new(default_options());
    client
        .connect(Arc::clone(&server.client))
        .await
        .expect("connect");

    // Abort with a custom reason string.
    let signal = tokio_util::sync::CancellationToken::new();
    let options = McpRequestOptions {
        signal: Some(signal.clone()),
        abort_reason: Some("user cancelled".to_string()),
        ..McpRequestOptions::default()
    };
    let pending = {
        let client = client.clone();
        tokio::spawn(async move { client.request("slow", None, options).await })
    };
    tokio::time::sleep(std::time::Duration::from_millis(10)).await;
    signal.cancel();
    let error = pending.await.expect("task").expect_err("aborted");
    assert_eq!(
        error.message().as_ref(),
        expected["abortError"]["message"].as_str().unwrap()
    );
    tokio::time::sleep(std::time::Duration::from_millis(10)).await;
    flush().await;
    let expected_cancel_notifications: Vec<String> = expected["cancelNotifications"]
        .as_array()
        .unwrap()
        .iter()
        .map(|value| value.as_str().unwrap().to_string())
        .collect();
    assert_eq!(
        &server.requests_for("notifications/cancelled")[..],
        &expected_cancel_notifications[..]
    );

    // Timeout: silent server, timeoutMs=10 -> McpTimeoutError + cancellation.
    let error = client
        .request(
            "slow",
            None,
            McpRequestOptions {
                timeout_ms: Some(10),
                ..McpRequestOptions::default()
            },
        )
        .await
        .expect_err("timeout");
    assert_eq!(
        error.to_string(),
        expected["timeoutError"]["message"].as_str().unwrap()
    );
    let McpClientError::Timeout(timeout_ms) = error else {
        panic!("expected timeout, got {error:?}");
    };
    assert_eq!(
        timeout_ms,
        expected["timeoutError"]["timeoutMs"].as_u64().unwrap()
    );
    tokio::time::sleep(std::time::Duration::from_millis(10)).await;
    flush().await;
    let expected_after: Vec<String> = expected["afterTimeoutCancels"]
        .as_array()
        .unwrap()
        .iter()
        .map(|value| value.as_str().unwrap().to_string())
        .collect();
    assert_eq!(
        &server.requests_for("notifications/cancelled")[..],
        &expected_after[..]
    );

    // timeoutMs=0 disables the timer entirely.
    let late = client
        .request(
            "eventual",
            None,
            McpRequestOptions {
                timeout_ms: Some(0),
                ..McpRequestOptions::default()
            },
        )
        .await
        .expect("zero timeout disables the timer");
    assert_canonical("late", late, &expected["zeroTimeout"]);

    // Aborting before sending fails fast.
    let pre_aborted = tokio_util::sync::CancellationToken::new();
    pre_aborted.cancel();
    let error = client
        .request(
            "slow",
            None,
            McpRequestOptions {
                signal: Some(pre_aborted),
                ..McpRequestOptions::default()
            },
        )
        .await
        .expect_err("pre-aborted");
    assert_eq!(
        error.message().as_ref(),
        expected["preAborted"]["message"].as_str().unwrap()
    );
    client.close().await.expect("close");
}

#[tokio::test(start_paused = true)]
async fn client_server_requests_match_the_capture() {
    let expected = &oracle()["client_server_requests"];
    let server = MemoryServer::new().await;
    server.set_handler(
        "initialize",
        value_handler(json!({
            "protocolVersion": "2025-06-18",
            "capabilities": { "roots": { "listChanged": true } },
            "serverInfo": { "name": "s", "version": "1" },
        })),
    );
    let mut options = default_options();
    options.roots = Some(roots(&[("file:///w", Some("w")), ("file:///x", None)]));
    let client = McpClient::new(options);
    client
        .connect(Arc::clone(&server.client))
        .await
        .expect("connect");

    // Deliver server-to-client requests directly at the client transport and
    // capture the client's responses at the server side.
    let next_server_id = Arc::new(std::sync::atomic::AtomicI64::new(100));
    let ask = {
        let server_transport = Arc::clone(&server.server);
        move |method: &str, params: Option<Value>| -> BoxFuture<'static, String> {
            let id = next_server_id.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
            let transport = Arc::clone(&server_transport);
            let method = method.to_string();
            Box::pin(async move {
                let (sender, receiver) = tokio::sync::oneshot::channel::<Value>();
                let expected_id = JsonRpcId::Number(serde_json::Number::from(id));
                let sender_cell = Arc::new(Mutex::new(Some(sender)));
                let listener: TransportMessageListener = Arc::new(move |message| {
                    if let JsonRpcMessage::Response(response) = message {
                        if response.id() == &expected_id {
                            if let Some(sender) = sender_cell.lock().expect("sender").take() {
                                let _ = sender
                                    .send(JsonRpcMessage::Response(response.clone()).to_value());
                            }
                        }
                    }
                });
                let unsubscribe = transport.on_message(listener);
                transport
                    .send(&JsonRpcMessage::Request {
                        id: JsonRpcId::Number(serde_json::Number::from(id)),
                        method: method.clone(),
                        params,
                    })
                    .await
                    .expect("send request");
                let response = receiver.await.expect("client response");
                unsubscribe.unsubscribe();
                stringify(&response)
            })
        }
    };

    assert_eq!(
        ask("ping", None).await,
        expected["pingResponse"].as_str().unwrap()
    );
    assert_eq!(
        ask("roots/list", None).await,
        expected["rootsResponse"].as_str().unwrap()
    );
    // Handler returning null -> result {}.
    client.set_request_handler(
        "sample",
        Arc::new(
            |_params: Option<Value>, _context: crate::mcp::client::RequestContext| {
                Box::pin(async { Ok(Value::Null) }) as RequestHandlerFuture
            },
        ),
    );
    assert_eq!(
        ask("sample", Some(json!({ "a": 1 }))).await,
        expected["nullHandlerResponse"].as_str().unwrap()
    );
    // Handler failing with McpError (with data).
    client.set_request_handler(
        "fail",
        Arc::new(
            |_params: Option<Value>, _context: crate::mcp::client::RequestContext| {
                Box::pin(async {
                    Err(McpClientError::Mcp(
                        McpError::new(-32000, "no can do")
                            .with_data(json!({ "hint": "try again" })),
                    ))
                }) as RequestHandlerFuture
            },
        ),
    );
    assert_eq!(
        ask("fail", None).await,
        expected["mcpErrorResponse"].as_str().unwrap()
    );
    // Handler failing with a plain error -> internalError without data.
    client.set_request_handler(
        "fail2",
        Arc::new(
            |_params: Option<Value>, _context: crate::mcp::client::RequestContext| {
                Box::pin(async { Err(McpClientError::Other("plain boom".to_string())) })
                    as RequestHandlerFuture
            },
        ),
    );
    assert_eq!(
        ask("fail2", None).await,
        expected["plainErrorResponse"].as_str().unwrap()
    );
    // Unknown method -> methodNotFound.
    assert_eq!(
        ask("no/such/method", None).await,
        expected["notFoundResponse"].as_str().unwrap()
    );

    // Rootless client has no roots/list handler.
    let rootless_server = MemoryServer::with_minimal_initialize().await;
    let rootless = McpClient::new(default_options());
    rootless
        .connect(Arc::clone(&rootless_server.client))
        .await
        .expect("connect");
    let (sender, receiver) = tokio::sync::oneshot::channel::<Value>();
    let expected_id = JsonRpcId::Number(serde_json::Number::from(500));
    let sender_cell = Arc::new(Mutex::new(Some(sender)));
    let listener: TransportMessageListener = Arc::new(move |message| {
        if let JsonRpcMessage::Response(response) = message {
            if response.id() == &expected_id {
                if let Some(sender) = sender_cell.lock().expect("sender").take() {
                    let _ = sender.send(JsonRpcMessage::Response(response.clone()).to_value());
                }
            }
        }
    });
    rootless_server.server.on_message(listener);
    rootless_server
        .server
        .send(&JsonRpcMessage::Request {
            id: JsonRpcId::Number(serde_json::Number::from(500)),
            method: "roots/list".to_string(),
            params: None,
        })
        .await
        .expect("send");
    assert_eq!(
        stringify(&receiver.await.expect("response")),
        expected["noRootsResponse"].as_str().unwrap()
    );

    // Notifications reach listeners; a panicking listener surfaces on the
    // error listeners (upstream catches listener throws and re-emits).
    let seen = Arc::new(Mutex::new(Vec::new()));
    let errors = Arc::new(Mutex::new(Vec::new()));
    let listener_seen = Arc::clone(&seen);
    let unsubscribe = client.on_notification(
        "custom/event",
        Arc::new(move |params: &Value| {
            if params.get("bad") == Some(&json!(true)) {
                panic!("listener boom");
            }
            listener_seen.lock().expect("seen").push(params.clone());
        }),
    );
    let error_log = Arc::clone(&errors);
    client.on_error(Arc::new(move |error: &McpClientError| {
        error_log.lock().expect("errors").push(error.to_string());
    }));
    let _ = server
        .server
        .send(&JsonRpcMessage::Notification {
            method: "custom/event".to_string(),
            params: Some(json!({ "v": 1 })),
        })
        .await;
    let _ = server
        .server
        .send(&JsonRpcMessage::Notification {
            method: "custom/event".to_string(),
            params: Some(json!({ "bad": true })),
        })
        .await;
    tokio::time::sleep(std::time::Duration::from_millis(20)).await;
    let listener_errors = errors.lock().expect("errors").clone();
    assert_eq!(listener_errors[0], "listener boom");
    assert_canonical(
        "notifications",
        Value::Array(seen.lock().expect("seen").clone()),
        &expected["notifications"],
    );
    unsubscribe.unsubscribe();
    let _ = server
        .server
        .send(&JsonRpcMessage::Notification {
            method: "custom/event".to_string(),
            params: Some(json!({ "v": 2 })),
        })
        .await;
    tokio::time::sleep(std::time::Duration::from_millis(20)).await;
    assert_canonical(
        "after unsubscribe",
        Value::Array(seen.lock().expect("seen").clone()),
        &expected["afterUnsubscribe"],
    );
    // Unknown response id surfaces on the error listeners. (The invalid
    // JSON-RPC message case is a transport-level rejection — in-memory
    // deliveries are already parsed — so it is covered by the jsonrpc parse
    // table instead; see the module docs.)
    let _ = server
        .server
        .send(&JsonRpcMessage::Response(JsonRpcResponse::Success {
            id: JsonRpcId::Number(serde_json::Number::from(424242)),
            result: json!({}),
        }))
        .await;
    tokio::time::sleep(std::time::Duration::from_millis(20)).await;
    let all_errors = errors.lock().expect("errors").clone();
    assert_eq!(
        all_errors[1],
        expected["errorListener"][1].as_str().unwrap()
    );
    client.close().await.expect("close");
}

#[tokio::test(start_paused = true)]
async fn client_transport_close_matches_the_capture() {
    let expected = &oracle()["client_transport_close"];
    let server = MemoryServer::with_minimal_initialize().await;
    server.set_handler("ping", value_handler(json!({})));
    server.set_handler("slow", never_handler());
    let client = McpClient::new(default_options());
    client
        .connect(Arc::clone(&server.client))
        .await
        .expect("connect");
    let close_events = Arc::new(Mutex::new(Vec::new()));
    let log = Arc::clone(&close_events);
    client.on_close(Arc::new(move || {
        log.lock().expect("close events").push("closed".to_string());
    }));
    let pending = {
        let client = client.clone();
        tokio::spawn(async move {
            client
                .request("slow", None, McpRequestOptions::default())
                .await
        })
    };
    // The transport drops mid-request (the request is already registered).
    flush().await;
    let _ = server.client.close().await;
    let error = pending.await.expect("task").expect_err("rejected");
    assert_eq!(
        error.message().as_ref(),
        expected["rejected"]["message"].as_str().unwrap()
    );
    let expected_events: Vec<String> = expected["closeEvents"]
        .as_array()
        .unwrap()
        .iter()
        .map(|value| value.as_str().unwrap().to_string())
        .collect();
    assert_eq!(
        &close_events.lock().expect("events").clone()[..],
        &expected_events[..]
    );
    assert_eq!(client.connection_state(), ClientState::Closed);
    let error = client
        .ping(McpRequestOptions::default())
        .await
        .expect_err("ping after close");
    assert_eq!(
        error.message().as_ref(),
        expected["pingAfterClose"]["message"].as_str().unwrap()
    );
    client.close().await.expect("second close");
    assert_eq!(
        close_events.lock().expect("events").len(),
        expected["closeEventsAfterDoubleClose"]
            .as_array()
            .unwrap()
            .len()
    );
}

/// The `./testing` entry surface stays reachable from the tests.
#[test]
fn unsubscribe_type_is_public_surface() {
    let (client, _server) = create_in_memory_transport_pair();
    let unsubscribe: Unsubscribe = client.on_message(Arc::new(|_: &_| {}));
    unsubscribe.unsubscribe();
    drop(client.start());
}
